from author_library import *
cards=[]
for name,key,desc in [('文依来','wen_yilai','一直被追问出身的青年'),('文依来的双生弟弟','wen_yilai_brother','由笛立医生抚养、与母亲一起生活的青年')]:
    bio=f'{name}是伦伦与遇难外星航行者的儿子，也是{desc}。他的成长被成年人对血统、能力和利益的安排切开，与自己的兄弟长期分离；外貌接近人类，并不让人愿意停止追问他究竟是什么。他的身体能够产生电流，独处时的效果有限，真正的转折发生在两兄弟接触之后：彼此脑中的信息交流，连父亲遗传留下却未被唤起的内容也开始进入意识。他们理解了父亲未完的宇宙航行，因而选择离开地球。面对笛立的操纵，他们没有简单复仇，仍愿意感谢养育之恩；面对武装者，则先毁去枪械，表现出力量与不滥杀可以同时存在。与母亲告别的痛苦也没有被所谓高等血统抹掉。他们以电网排开泥浆，进入父亲的飞船，带着尚未完全解放的航行知识出发。终局的{name}不是可以单独复制兄弟合击威力的电神：强放电、信息互通和电网都依赖两人的结合，宇航则依靠遗留飞船。应保留对母亲的情感、对陌生身份的迟疑和出发的坚决，不能把笛立声称的“几乎任何事”当作真实能力上限。'
    cards.append(compact(key,name,bio,'与双生兄弟乘父亲遗留飞船离开地球，去完成未竟航行；后续返回未证实','主角','理解自身来历并完成父亲未竟的航行，不再任由成年人把自己当商品。',
    '有礼而直接，对亲人保有温情；身世压力下也会显出黯然。','与兄弟联系后优先解除武装威胁，仍给养育者体面告别的机会。','感谢养育不等于交出未来，血统带来的信息需要自己作出选择。',
    [ab('生物电流','异于地球人的身体产生电流；兄弟接触可大幅增强并形成排开泥浆的电网。','单独只证实较弱电流，终局强表现需双方合作；不赋予无限能源。',kind='生物电'),ab('双生信息互通','接触时交换脑中记忆，并激活遗传信息。','限这对兄弟的明确机制，不是触碰任何人就能复制其知识。',kind='信息能力'),ab('继承飞船航行','使用父亲留下的飞船与逐渐唤起的遗传知识完成任务。','飞船是实体资产，未在场、失能或受损时不能用肉身代替宇航。',kind='装备')],
    [ev('068',3363,3395,'接触交换信息及单独弱、共同强的限制'),ev('068',3419,3452,'遗传任务与解除武装'),ev('068',3461,3509,'电网排泥和飞船离开')],profile='ordinary',extra={'baseline':{'destruction':'合力电流可迅速使现场机枪弯曲变形；个人独处威力远小。','durability':'身体与人类不同，但无充分证据说明可承受任意枪弹；电网只按排泥与防护的具体表现。','speed':'施放电流反应快；宇航速度属于父亲飞船，不算肉身速度。','energy':'生物电输出，合力增强明显，能源与极限未量化。','mind':'可与双生兄弟交换记忆，未证实免疫精神控制。'},'uncertainties':['合力峰值不得由任何一张单人卡无条件独占。','文依来弟弟的独立姓名未明确，使用稳定描述而不造名。'] if key.endswith('brother') else ['兄弟合力峰值不能算单人常态。']}))
    rate(cards[-1],[2,3,2,3,3,5],(1,3,1),'凶','单独电流有限；可控上限需兄弟共同接触，能毁坏现场多件枪械和形成排泥电网。',mastery='基本掌握')
    cards[-1]['rating_input']['ceiling']['description']='兄弟到场并互相接触后增强电流，形成电网；携带父亲飞船时另有宇航能力。'
cards.append(compact('lun_lun','伦伦',
 '伦伦是澳洲刚刚族的女子，她与遭遇事故的外星航行者相识，面对的是一个连表达都变得困难的伴侣，而不是抽象的神话。她生下双生子，非人协会因无人会接生而请来笛立医生，这个看似实际的选择却让家庭被利益切开。笛立用孩子会被带走的说法打动她，她希望至少把一个孩子留在身边，于是接受了后来造成分离的安排。母亲的愿望被人利用，并不意味着她没有自己的判断；兄弟重聚后，她既为他们的能力骄傲，也明白遗传信息会把他们引向父亲未完的远行。孩子邀请她一起去，她没有强迫他们留下，也没有勉强自己离开熟悉的地方。告别时的伤心、骄傲和选择同时存在。她甚至在卫斯理凶视笛立时挡到对方面前，说明情感关系不能简单按善恶名单一刀割断。最后她请求住在端纳的建筑中，留在地球；没有证据表明她本人能放电、控制飞船或继承儿子的全部本领。参战时她的重要性是一个能够爱、犹疑、受骗又重新作选择的人，而不是只供超能力青年解释血统的背景道具。',
 '《电王》末留在地球，请求居住在端纳的建筑中，两个儿子已远行','主角','保护孩子并保持与自己生活、感情和故土相容的选择。',
 '以具体亲情和生活经验理解变化，不用抽象技术名词掩盖感受。','孩子受到买卖或伤害时会保护他们，离别到来时仍尊重其成长。','孩子属于自己的未来，母亲的爱不能等同永远占有。',
 [ab('家族历史与沟通','保留丈夫曾艰难传达的往事，能与孩子及相关人物交流。','不是读心或遗传知识数据库；儿子的电流能力不属于她。')],
 [ev('068',3409,3435,'父亲遗言、母子关系及拒绝同行'),ev('068',3483,3487,'保护笛立的复杂关系'),ev('068',3515,3534,'最终居所和当年被利用的母性')],profile='ordinary'))
cards.append(compact('di_li','笛立医生',
 '笛立医生原本因接生这件最普通而必要的事，接触到非人协会无法自行处理的家庭。他知道双生子有异常来历，逐渐把照顾和利益算计缠在一起。他利用伦伦害怕两个孩子都被带走的心情，参与把兄弟分开的安排，又以红头老爹的身份隐藏生活，使外界很难追到真正来历。养育并非完全虚假，但他会把养育变成控制孩子的理由；当文依来兄弟表现出强大电流，他首先想到的仍是地球上的荣华富贵。到事件高潮，他与武装势力联系，准备把两个青年交给能够出价的组织，反而被他们解除威胁。兄弟并没有因他的算计就拒绝承认养育之恩，他却做贼心虚，连友善的握手也不敢接受。孩子离开地球后，伦伦仍挡在他面前，而他选择跟那些武装者走，声称对方还需要自己的故事。终局的笛立没有获得孩子的发电能力，也没有控制他们的飞船；他的危险在于专业入口、长期保密和把亲密关系变成筹码。演绎应让照料的历史与逐利的选择同时可见，不把一个复杂的养育者写成只会喊征服世界的恶人。',
 '《电王》末失去对兄弟的控制，随武装组织人员离开，去向未进一步交代','反派','把掌握的异常秘密和养育关系转成财富与地位。',
 '习惯控制消息和身份，用照料者的资历要求别人信任。','孩子要离开时诉诸养育之恩，利益失败后转而出售自己所知的故事。','他把付出视为可以索取未来的凭据，容易低估孩子的自主。',
 [ab('医学接触与长期隐蔽','医生身份让他接触特殊家庭，靠伪装、迁居与信息隔离维持秘密。','没有独立超能力，武装组织和外星子女都不是能随意控制的工具。')],
 [ev('068',3172,3199,'红头老爹身份与买主关联'),ev('068',3379,3391,'用养育关系控制的失败'),ev('068',3485,3524,'武装买主、畏惧握手与最后离去')],profile='ordinary',aliases=['红头老爹']))
cards.append(compact('yaoming_shouzi','要命的瘦子',
 '要命的瘦子以职业杀手的危险名声进入文依来身世事件。他所处的世界按委托、报酬、目标和保密运作，人命和线索都可以成为交易的一部分；这种行动逻辑与非人协会的研究兴趣、伦伦的母爱以及兄弟的身世选择彼此碰撞。他知道与泥淖有关的地点，也留下了一把可能牵涉财富的钥匙，说明他不是只在街角举枪的一次性影子。然而他能追踪和威胁人，并不代表理解目标身体里隐藏的全部机制。与文依来接触时，青年在强烈惊惶愤怒中抓住他的手腕，随后发生致命结果；卫斯理把死亡与电流相联，也保留原有心脏问题可能参与的推测。死因的某个细节未明，并不改变他已经死亡、无法继续执行委托的事实。终局若让他参战，需明示恢复最后可行动肉身并保留结局记忆，原作没有给他复活。这个人物的演绎重点是职业暴力遇到未知目标后的判断：他可能先估价、试探和避开无把握的接触，而不是因“要命”外号获得必中或不死能力。',
 '《电王》中死亡；部署为明确改编的最后可行动肉身并保留终局记忆','反派','以职业暴力完成有利可图的委托，并保住行动优势。',
 '估计目标、距离、报酬和风险，不轻易公开掌握的路线。','发现目标有未识别的身体能力时试图重建距离与信息优势。','名声有用，但未知机制足以让熟练暴力失效。',
 [ab('职业追踪与威胁','杀手经验及秘密行动方式。','不能按外号推定必杀、绝对潜行或对异常生理的免疫。')],
 [ev('068',2917,2919,'致命接触与死因推测'),ev('068',3025,3026,'知晓泥淖位置'),ev('068',3461,3466,'死亡后留下钥匙并与其他人的结局对照')],profile='investigator',extra={'adaptations':[{'change':'恢复其最后可独立行动的肉身，保留被异常电流击倒的终局记忆。','reason':'让已死角色能参与新场景，同时不冒称原作复活。','power_impact':'不提高肉体或杀伤能力，仍会被未知能力克制。'}],'uncertainties':['电流是否与原有心脏问题共同致死，原文只作推测。']}))
save([c for c in cards if c['id']!='weisili_lun_lun'])
